CREATE TABLE videos (id UUID PRIMARY KEY, filename TEXT NOT NULL, filepath TEXT NOT NULL, duration DOUBLE PRECISION, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE analysis_jobs (id UUID PRIMARY KEY, video_id UUID NOT NULL REFERENCES videos(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK (status IN ('queued','processing','completed','failed')), progress INTEGER NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100), error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ);
CREATE TABLE violations (id UUID PRIMARY KEY, job_id UUID NOT NULL REFERENCES analysis_jobs(id) ON DELETE CASCADE, confidence DOUBLE PRECISION NOT NULL, timestamp DOUBLE PRECISION NOT NULL, duration DOUBLE PRECISION NOT NULL, supporting_frames INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE evidence (id UUID PRIMARY KEY, violation_id UUID NOT NULL REFERENCES violations(id) ON DELETE CASCADE, evidence_type TEXT NOT NULL CHECK (evidence_type IN ('frame','annotated_video')), filepath TEXT NOT NULL, confidence DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_jobs_video_id ON analysis_jobs(video_id); CREATE INDEX idx_violations_job_id ON violations(job_id); CREATE INDEX idx_evidence_violation_id ON evidence(violation_id);
